// ──────────────────────────── tests ──────────────────────────────────────

Test("singletons are shared by the root and every scope", () =>
{
    var root = new Container();
    root.Register(Lifetime.Singleton, _ => new Clock());
    var a = root.Resolve<Clock>();
    Ok(ReferenceEquals(a, root.Resolve<Clock>()), "same instance from the root");
    Ok(ReferenceEquals(a, root.CreateScope().Resolve<Clock>()), "same instance from a scope");
});

Test("scoped instances are per scope", () =>
{
    var root = new Container();
    root.Register(Lifetime.Scoped, _ => new Repo());
    var s1 = root.CreateScope();
    var s2 = root.CreateScope();
    Ok(ReferenceEquals(s1.Resolve<Repo>(), s1.Resolve<Repo>()), "same within a scope");
    Ok(!ReferenceEquals(s1.Resolve<Repo>(), s2.Resolve<Repo>()), "different across scopes");
});

Test("resolving a scoped service from the root throws", () =>
{
    var root = new Container();
    root.Register(Lifetime.Scoped, _ => new Repo());
    Throws<InvalidOperationException>(() => root.Resolve<Repo>());
});

Test("transients are new every time", () =>
{
    var root = new Container();
    root.Register(Lifetime.Transient, _ => new Repo());
    Ok(!ReferenceEquals(root.Resolve<Repo>(), root.Resolve<Repo>()), "two different instances");
});

Test("factories resolve their dependencies from the same container", () =>
{
    var root = new Container();
    root.Register(Lifetime.Singleton, _ => new Clock());
    root.Register(Lifetime.Scoped, c => new OrderService(c.Resolve<Repo>(), c.Resolve<Clock>()));
    root.Register(Lifetime.Scoped, _ => new Repo());
    var scope = root.CreateScope();
    var svc = scope.Resolve<OrderService>();
    Ok(ReferenceEquals(svc.Repo, scope.Resolve<Repo>()), "the service got the scope's repo");
});

Test("an unregistered type throws (boundary)", () =>
    Throws<InvalidOperationException>(() => new Container().Resolve<Clock>()));

