drills.solutionTail:
// ──────────────────────────── types ──────────────────────────────────────

enum Lifetime { Singleton, Scoped, Transient }

class Clock;
class Repo;
class OrderService(Repo repo, Clock clock) { public Repo Repo { get; } = repo; public Clock Clock { get; } = clock; }

class Container
{
    private readonly Dictionary<Type, (Lifetime Lifetime, Func<Container, object> Factory)> _registrations;
    private readonly Dictionary<Type, object> _singletons;
    private readonly Dictionary<Type, object> _scoped = new();
    private readonly bool _isRoot;

    public Container() : this(new(), new(), isRoot: true) { }

    private Container(Dictionary<Type, (Lifetime, Func<Container, object>)> registrations, Dictionary<Type, object> singletons, bool isRoot)
    {
        _registrations = registrations;
        _singletons = singletons;
        _isRoot = isRoot;
    }

    public void Register<T>(Lifetime lifetime, Func<Container, T> factory) where T : class =>
        _registrations[typeof(T)] = (lifetime, c => factory(c));

    public T Resolve<T>() where T : class
    {
        if (!_registrations.TryGetValue(typeof(T), out var reg)) throw new InvalidOperationException($"No service for type {typeof(T).Name} has been registered.");
        switch (reg.Lifetime)
        {
            case Lifetime.Singleton:
                if (!_singletons.TryGetValue(typeof(T), out var single)) _singletons[typeof(T)] = single = reg.Factory(this);
                return (T)single;
            case Lifetime.Scoped:
                if (_isRoot) throw new InvalidOperationException($"Cannot resolve scoped service {typeof(T).Name} from the root container.");
                if (!_scoped.TryGetValue(typeof(T), out var scoped)) _scoped[typeof(T)] = scoped = reg.Factory(this);
                return (T)scoped;
            default:
                return (T)reg.Factory(this);
        }
    }

    public Container CreateScope() => new(_registrations, _singletons, isRoot: false);
}

drills.explanation:
Share the registrations and the singleton dictionary between the root and its scopes; give each scope its own scoped dictionary:

```csharp
case Lifetime.Scoped:
    if (_isRoot) throw new InvalidOperationException(...);
    if (!_scoped.TryGetValue(typeof(T), out var scoped)) _scoped[typeof(T)] = scoped = reg.Factory(this);
    return (T)scoped;
```

Passing `this` to the factory is what lets a scoped `OrderService` receive the SAME scope's `Repo`. (A production container also builds singletons from the root so a singleton can never capture a scoped dependency, and disposes what it created.)
